    v = lambda sc, m, **k: mae(D, sc, m, **k)  # noqa: E731
    rel = lambda sc, m: pct(v(sc, m), v(sc, "xgb_rolling"))  # noqa: E731
    pr = lambda sc, m: pair(D, sc, "xgb_rolling", m)  # noqa: E731
    f = fm

    def vw(sc, m):
        r, p = rel(sc, m), pr(sc, m)
        if p is None:
            return "немає даних"
        return ("значуще краще" if r < 0 else "значуще гірше") if p["p"] < 0.05 else "без значущої різниці"

    def dep(sc, split="test"):
        return [pe(D, sc, m, "depth_MAE", split) for m in ("persistence", "ridge_depth", "xgb_direct")]

