    rp, rn, ro = (pt(D, sc, "ridge_depth", "depth", "test") for sc in ("price", "net_import", "outages"))
    rpv = pt(D, "price", "ridge_depth", "depth", "validation")
    dp, dn, do = (dep(sc) for sc in ("price", "net_import", "outages"))
