    pl = {sc: D[sc]["cp"]["pelt"]["scores"] for sc in SCEN}
    nr = {sc: refit_counts(D, sc, "xgb_drift") for sc in SCEN}
    na = {sc: refit_counts(D, sc, "xgb_adaptive") for sc in SCEN}
    syn = D["syn"]["m"]
    sv = lambda m, s: float(syn[(syn["model"] == m) & (syn["split"] == "test") & (syn["subset"] == s)]["MAE"].iloc[0])  # noqa: E731
    C = {}

