    q(G3, "Чому горизонт 24 години?", "Це відповідає ринку на добу наперед: заявки на наступну добу подаються до 12:00 попередньої. Лаги коротші за 24 години в момент випуску прогнозу недоступні.")
    q(G3, "Що таке walk-forward?", "Перенавчання вперед по часу: у момент T модель навчається на даних до T і прогнозує наступний відрізок, потім усе повторюється. Так імітується реальне використання.")
    q(G3, "Чому погода фактична? Чи це проблема?", "Так, це припущення про «ідеальний прогноз погоди». Воно однаково діє на всі моделі, але реальні результати були б трохи гіршими. Воно названо в обмеженнях.")
    q(G3, "Як ви підбирали параметри?", "Лише на валідації: Optuna (20 спроб) із TimeSeriesSplit для гіперпараметрів XGBoost; сітка для ширини вікна й порога тривоги; для тригерів «після атаки» і «за помилками» — окрема сітка (вікно, допуск k, рівень h) командою tune-triggers. Тест не використовувався.")
    q(G3, "Чому тест Вілкоксона, а не t-тест?", "Вілкоксон — непараметричний, не вимагає нормальності похибок, парний (порівнюємо два методи на тих самих днях або подіях). Для прогнозів на добу — на добових MAE, для прогнозу після атаки — на помилках подій. Але похибки автокорельовані, а події перекриваються, тому p-значення оптимістичні.")
    q(G3, "Що таке абляція і навіщо вона?", "Експеримент, у якому прибирають один елемент. «Ковзне вікно» — той самий розклад перенавчання, але без тригера; «кожні 3 дні» — те саме, але частіше. Якщо тригерна модель не краща за них, тригер нічого не додав.")
    q(G4, "Як працює BOCPD простими словами?", "Він веде облік довжини поточного режиму. Щодня для кожної можливої довжини оновлює ймовірність за тим, наскільки нове значення схоже на цей режим. Якщо ймовірність того, що режим розпочався щойно (не більше 3 діб тому), перевищує поріг, подається тривога.")
    q(G4, "Що таке hazard і навіщо?", "Апріорна ймовірність зламу в будь-який день = 1 / очікувана тривалість режиму. Я задала 120 діб (відключення) і 250 діб (інші ряди); це параметри конфігурації, на валідації не підбирались.")
    q(G4, "Чому сигнал — ймовірність «довжина режиму ≤ 3 доби»?", "За сталого hazard ймовірність нульової довжини режиму завжди дорівнює самому hazard і не несе інформації. Тому беремо накопичену ймовірність невеликих довжин.")
    q(G4, "Чим PELT відрізняється від BOCPD?", "PELT — офлайн: бачить увесь ряд і знаходить оптимальні точки зламу; точний, але використовує майбутнє. BOCPD — онлайн: у кожний момент використовує лише минуле, тому придатний для керування перенавчанням.")
    q(G4, "Що таке CUSUM і як він працює у вашій роботі?", "Накопичувальна сума: щодня беремо відносне перевищення добової MAE моделі над її середнім за попередні 60 діб, віднімаємо допуск k і додаємо до суми (не нижче нуля). Коли сума перевищує рівень h — це дрейф помилки, і модель перенавчається на короткому вікні. Одноразовий викид обмежений, щоб один поганий день не запускав тривогу. k, h і вікно підібрано на валідації.")
    q(G4, "Чому стандартизація за статистиками навчального періоду і що таке нижня межа масштабу?", "Щоб сигнал був причинним (не використовував майбутнє). Ряд відключень здебільшого нулі, тож його стандартне відхилення на навчанні крихітне — і будь-яке відхилення здавалося б величезним. Нижня межа масштабу цьому запобігає.")
    q(G4, "Чому XGBoost, а не LSTM?", "XGBoost швидкий, добре працює на табличних ознаках і інтерпретується. LSTM реалізовано й перевірено на синтетиці, але образ Docker зібрано без TensorFlow (дуже великий), тому в реальні експерименти не включено — це в плані.")
    q(G4, "Чому Prophet такий поганий?", "Його лінійний тренд, навчений на 2019–2021, у наступні роки екстраполюється (до 8000 МВт для імпорту). Він не знає про режими. Це недолік цієї базової моделі; тому додано сезонний наївний як чесну просту базу.")
    q(G5, "Як саме ви прогнозуєте глибину й тривалість після атаки?", "У день видачі d0 (день удару зі списку або день тривоги BOCPD) модель бачить лише історію до d0 і прогнозує на 30 діб уперед. Глибина — найвищий добовий рівень, тривалість — діб до трьох спокійних діб поспіль. Є траєкторні методи (XGBoost прогнозує шлях) і прямі (одразу глибину чи тривалість): ridge-регресія й XGBoost напряму для глибини; XGBoost-регресія, модель виживання AFT і класифікатор для тривалості.")
    q(G5, "Що таке «як учора» (персистентність) і чому це база?", "Рівень останньої доби до дня видачі тримається без змін. Після удару рівень дефіциту зазвичай довго лишається, тож це сильний простий метод; перевершити його — змістовна вимога.")
    q(G5, "Чому пряма ridge-модель виграє на глибині?", "Імовірне пояснення: лінійна регресія на рівнях ряду (остання доба, середні й максимуми за 7 і 28 діб) екстраполює на нові рівні, а дерева XGBoost не виходять за межі значень, побачених у навчанні. Після удару, що виводить ряд на новий рівень, це важливо. Це пояснення, а не доведений факт.")
    q(G5, "Скільки подій і чи вистачає для висновків?", f"У тесті: ціна {n_price}, імпорт {n_ni}, відключення {n_out}, попит {n_dem}. Для ціни й імпорту подій достатньо для парного тесту; для попиту — ні, тому значущість не оцінюється. Події перекриваються (30-добові вікна), тому p-значення оптимістичні.")
    q(G5, "А тривалість?", "Реалізовано й перевірено три підходи (регресія, модель виживання AFT, класифікатор); точність поки на рівні базового методу «як учора». Тривалість залежить від майбутніх ударів і ремонтів, яких на момент прогнозу ми не знаємо; частина подій цензурована (дефіцит не закінчився за 30 діб); подій небагато. Потрібні: більше подій, дані про втрачену потужність і ремонти. Тому це напрям вдосконалення, а ключовий результат — глибина. (Точні числа — у таблиці «Числа, які треба знати» та на слайді про тривалість.)")
    q(G5, "Що таке цензурування і навіщо модель виживання?", "Цензурування — коли подія ще не сталася на момент закінчення спостереження (дефіцит не закінчився за 30 діб). Проста регресія змусила б вважати це «тривалість = 30», що спотворює оцінку; модель виживання AFT враховує, що справжня тривалість не менша.")
    q(G5, "Чому не можна передбачити перший удар 2022 року?", f"У навчанні немає жодної воєнної доби, а моделі (особливо дерева) не екстраполюють на небачений режим. Для втраченого попиту в тесті лише {n_dem} подій, тому значущість не оцінювалась. Це напрям вдосконалення: потрібні зовнішні знання про можливі режими.")
    q(G6, "Яке перенавчання краще: за розкладом, за тривогою, після атаки чи за помилкою?", f"Найкраще — часте перенавчання або перенавчання за власною помилкою моделі: за помилками проти щотижневого вікна — відключення {f(rel('outages', 'xgb_drift'), 1, sign=True)} % ({vw('outages', 'xgb_drift')}), попит {f(rel('demand', 'xgb_drift'), 1, sign=True)} % ({vw('demand', 'xgb_drift')}), імпорт {f(rel('net_import', 'xgb_drift'), 1, sign=True)} % ({vw('net_import', 'xgb_drift')}), ціна {f(rel('price', 'xgb_drift'), 1, sign=True)} % ({vw('price', 'xgb_drift')}). Тригер за рівнем BOCPD не обганяє часте перенавчання; після атаки — не краще.")
    q(G6, "Чому адаптивна модель із BOCPD не краща за ковзне вікно (за розкладом)?", f"Тривога BOCPD спізнюється на кілька діб, а сигнал за рівнем ряду менш чутливий, ніж помилка самої моделі. З усіх перенавчань за тривогою були лише {na['outages'][1]} із {na['outages'][0]} (відключення), {na['net_import'][1]} із {na['net_import'][0]} (імпорт); решта — за розкладом, тому різниця мала. Це пояснення, не доведений факт.")
    q(G6, "Навіщо контроль «ковзне вікно кожні 3 дні»?", "Тригерні моделі перенавчаються частіше за тижневий розклад. Без контролю можна помилково приписати виграш сигналу, хоча дала його частота перенавчання. Контроль із тим самим бюджетом перенавчань показує, що саме працює.")
    q(G6, "Чому на ціні статична модель не гірша за перенавчані?" if price_static_ok else "Як перенавчання працює на ціні?",
      (f"Ціна обмежена стелею й менш чутлива до зміни режиму; статична {f(v('price', 'xgb_static'), 3)} проти ковзного вікна {f(v('price', 'xgb_rolling'), 3)}. Це чесний результат: перенавчання допомагає там, де режим змінився (попит, відключення), а тут нічого не дає." if price_static_ok
       else f"На ціні перенавчання дає помірний виграш: статична {f(v('price', 'xgb_static'), 3)} проти ковзного вікна {f(v('price', 'xgb_rolling'), 3)}."))
    q(G6, "Чому перенавчання після атаки не допомогло?", "Нова модель після удару бачить лише короткий відрізок даних після нього; сигнал «був удар» не завжди означає зміну залежностей. Це гіпотеза; результат — без значущого виграшу, тому ідея в напрямах вдосконалення.")
    q(G7, "Який головний результат?", f"Глибину дефіциту після атаки можна прогнозувати значуще точніше за «як учора»: {deptxt('price')}; {deptxt('net_import')}. А перенавчання краще за статичну модель там, де змінився режим; найкраще — часте перенавчання або за помилкою моделі.")
    q(G7, "Чи значуща різниця між перенавчаною та статичною моделлю?", f"Статична проти щотижневого ковзного вікна: {static_line}. Для відключень і попиту різниця велика; для імпорту помірна. На відключеннях на валідації найкращою була статична — рейтинг між перенавчаними моделями нестійкий.")
    q(G7, f"Що означає MAE {f(v('net_import', 'xgb_rolling'), 0)} МВт?", f"У середньому прогноз чистого імпорту на годину відхиляється від факту приблизно на {f(v('net_import', 'xgb_rolling'), 0)} МВт. Діапазон значень — від −1 350 до +2 233 МВт.")
    q(G7, "Чому RMSE більший за MAE?", "RMSE зводить похибки в квадрат, тому великі промахи впливають сильніше.")
    q(G7, "Що показує виявлення зламів?", "BOCPD як діагностика: " + "; ".join(f"{SC_NAME[sc]} — {bo[sc]['n_detections']} тривог, точність {f(bo[sc]['precision'], 2)}, повнота {f(bo[sc]['recall'], 2)}" for sc in SCEN) + ". Повнота низька: багато ударів не залишають сліду в добових середніх. Тривоги разом з ударами задають дні подій для прогнозу після атаки.")
    q(G7, "Що дала перевірка на синтетичних даних?", f"Підтвердила, що пайплайн працює від початку до кінця: адаптивна {f(sv('xgb_adaptive', 'all'), 1)} проти {f(sv('xgb_static', 'all'), 1)} МВт статичної. Але дані згенеровані мною з вбудованими зламами, тому це перевірка коду, а не доказ для України.")
    q(G8, "Ви не підганяєте результат під бажаний висновок?", "Ні — частина результатів не збіглась з очікуванням (тригер BOCPD не обганяє часте перенавчання; тривалість на рівні базового методу), і я їх так і подала. Параметри підбирались лише на валідації. Застереження: базові моделі (наївний, ковзне вікно, контроль кожні 3 дні) додано після першого перегляду результатів на тесті; їхні параметри на тесті не підбирались, але вибір порівнянь не був повністю незалежним.")
    q(G8, "Ви знайшли помилку в коді — як вона вплинула?", "Ковзне вікно у виключений період не мало даних і ставало порожньою моделлю з прогнозом 0. Після виправлення (пропуск оновлення, якщо у вікні < 168 відомих значень) його похибка на відключеннях помітно впала; результати імпорту не змінились. Це застосовано до всіх моделей однаково.")
    q(G8, "Чи можна довіряти висновкам, якщо подій мало?", f"Лише як індикативним: події перекриваються (30-добові вікна), p-значення оптимістичні. Для ціни й імпорту подій {n_price} і {n_ni}, виграш стійкий (для ціни — на двох вибірках) — це підсилює довіру. Для відключень ({n_out}) і попиту ({n_dem}) висновків про виграш немає.")
    q(G8, "Чи це справжній дефіцит?", "Ні, це вимірювані наближення: попит залежить від допоміжної моделі, індекс відключень насичується на 1, імпорт обмежений лініями, ціна — стелею. Формулу балансу з теорії не перевірено через відсутність даних.")
    q(G8, "Якби ви мали більше часу, що б зробили?", "Додала б втрачену потужність за ударами й більше подій (для тривалості); перевірила б LSTM на реальних даних; використала б прогноз погоди замість фактичної; дослідила б чутливіші тригери перенавчання й блокові тести значущості.")
    q(G8, "Чому ваш результат щодо BOCPD «негативний» — це не провал?", "Негативний результат — теж результат: на цих даних тригер за рівнем BOCPD не обганяє просте часте перенавчання, але BOCPD корисний як діагностика (точність на відключеннях " + f(bo['outages']['precision'], 2) + ") і як джерело подій; працює тригер за власною помилкою моделі. Система відтворювана, тож іншу гіпотезу можна перевірити тими самими командами.")
    q(G8, "Ви самі написали код?", "Я проєктувала систему, ухвалювала рішення щодо методики, даних і інтерпретації. Реалізація виконувалась з використанням ШІ-асистента (Claude), я перевіряла результати, графіки й помилки. Якщо питання про це прямо поставлять — відповідайте чесно за вашою ситуацією; обговоріть із керівником, як це правильно подати.")
    q(G8, "Чому ви не порівняли з ARIMA?", "У теоретичній частині ARIMA описана як класичний метод, але вимагає стаціонарності, а ряди тут мають різкі режими. Сезонний наївний і Prophet подані як прості бази; ARIMA — у плані подальшої роботи.")
    C["qa"] = qa

